    fn from(data: Vec<(&'a str, u64)>) -> Self {
        let bars = data
            .into_iter()
            .map(|(label, value)| Bar::default().label(Line::from(label)).value(value))
            .collect();
        BarGroup {
            label: None,
            bars,
        }
    }
}

