        self.fg(Color::Cyan)
    }

    /// Sets the foreground color to dark cyan
    #[must_use]
    fn dark_cyan(self) -> Self {
        self.fg(Color::DarkCyan)
    }

    /// Sets the foreground color to white
    #[must_use]
    fn white(self) -> Self {
        self.fg(Color::White)
    }

    /// Sets the foreground color to gray
    #[must_use]
    fn gray(self) -> Self {
        self.fg(Color::Gray)
    }

    // Background colors

