impl FromStr for Color {
    type Err = ParseColorError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        // Normalize: strip spaces, hyphens, underscores, lowercase
        let normalized = s
            .chars()
            .filter(|c| !c.is_whitespace() && *c != '-' && *c != '_')
            .collect::<String>()
            .to_lowercase();

        // Map aliases: bright→light, grey→gray, silver→gray
        let normalized = match normalized.as_str() {
            s if s.starts_with("bright") => s.replace("bright", "light"),
            "grey" => "gray".to_string(),
            "darkgrey" => "darkgray".to_string(),
            "lightgrey" => "lightgray".to_string(),
            "silver" => "gray".to_string(),
            _ => normalized,
        };

        Ok(match normalized.as_str() {
            "reset" => Self::Reset,
            "black" => Self::Black,
            "red" => Self::Red,
            "green" => Self::Green,
            "yellow" => Self::Yellow,
            "blue" => Self::Blue,
            "magenta" => Self::Magenta,
            "cyan" => Self::Cyan,
            "gray" => Self::Gray,
            "darkgray" => Self::DarkGray,
            "lightred" => Self::LightRed,
            "lightgreen" => Self::LightGreen,
            "lightyellow" => Self::LightYellow,
            "lightblue" => Self::LightBlue,
            "lightmagenta" => Self::LightMagenta,
            "lightcyan" => Self::LightCyan,
            "white" => Self::White,
            _ => {
                // Try parsing as indexed color (u8)
                if let Ok(index) = s.parse::<u8>() {
                    Self::Indexed(index)
                } else if let (Ok(r), Ok(g), Ok(b)) = {
                    // Try parsing as hex color (#RRGGBB)
                    if !s.starts_with('#') || s.len() != 7 {
                        return Err(ParseColorError);
                    }
                    (
                        u8::from_str_radix(&s[1..3], 16),
                        u8::from_str_radix(&s[3..5], 16),
                        u8::from_str_radix(&s[5..7], 16),
                    )
                } {
                    Self::Rgb(r, g, b)
                } else {
                    return Err(ParseColorError);
                }
            }
        })
    }
}

