impl Constraint {
    pub fn apply(&self, length: u16) -> u16 {
        match *self {
            Constraint::Percentage(p) => {
                // Clamp percentage to 100 to avoid overflow
                let clamped_p = p.min(100);
                length.saturating_mul(clamped_p) / 100
            }
            Constraint::Ratio(num, den) => {
                // Handle Ratio(n, 0) gracefully - return 0
                if den == 0 {
                    return 0;
                }
                // Use saturating operations to avoid overflow
                let result = (num as u64)
                    .saturating_mul(length as u64)
                    .saturating_div(den as u64);
                result.min(u16::MAX as u64) as u16
            }
            Constraint::Length(l) => length.min(l),
            Constraint::Max(m) => length.min(m),
            Constraint::Min(m) => length.max(m),
        }
    }
}

